function stripFragment(url) {
	const i = url.indexOf("#");
	return i === -1 ? url : url.slice(0, i);
}

function deepCopy(value) {
	if (value === null || typeof value !== "object") return value;
	if (Array.isArray(value)) return value.map(deepCopy);
	if (value instanceof Date) return new Date(value.getTime());
	if (value instanceof RegExp) return new RegExp(value.source, value.flags);
	if (value instanceof Map) {
		const out = new Map();
		for (const [k, v] of value) out.set(deepCopy(k), deepCopy(v));
		return out;
	}
	if (value instanceof Set) {
		const out = new Set();
		for (const v of value) out.add(deepCopy(v));
		return out;
	}
	const out = {};
	for (const key of Object.keys(value)) out[key] = deepCopy(value[key]);
	return out;
}

export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	let ttl = ttlMs;
	if (ttl === undefined) ttl = 0;
	else if (!Number.isInteger(ttl) || ttl < 0) throw new RangeError("ttlMs must be an integer >= 0");

	const cache = new Map();
	const inflight = new Map();
	const counters = { hits: 0, misses: 0, fetches: 0 };

	const asResponse = (r) => ({ status: r.status, body: deepCopy(r.body) });

	async function performFetch(key) {
		counters.fetches++;
		const res = await fetchImpl(key);
		const stamp = now();
		const response = { status: res.status, body: deepCopy(res.body) };
		if (ttl > 0 && res.status >= 200 && res.status <= 299) cache.set(key, { ...response, stamp });
		return response;
	}

	function track(p, key) {
		const done = () => {
			if (inflight.get(key) === p) inflight.delete(key);
		};
		p.then(done, done);
	}

	function beginFetch(key) {
		const p = performFetch(key);
		inflight.set(key, p);
		track(p, key);
		return p;
	}

	async function get(url, opts) {
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		const key = stripFragment(url);
		const fresh = Boolean(opts && opts.fresh);

		if (!fresh) {
			const entry = cache.get(key);
			if (entry !== undefined) {
				if (now() - entry.stamp < ttl) {
					counters.hits++;
					return asResponse(entry);
				}
				cache.delete(key);
			}
		}

		counters.misses++;

		if (fresh || !inflight.has(key)) return asResponse(await beginFetch(key));
		return asResponse(await inflight.get(key));
	}

	return {
		get,
		clear(url) {
			if (url === undefined) cache.clear();
			else cache.delete(typeof url === "string" ? stripFragment(url) : url);
		},
		stats() {
			return { ...counters };
		},
	};
}
